\begin{aligned}
\operatorname{InitCert}_{Tab}(\Gamma,A,T,b)
\Longleftrightarrow{}&
\Gamma\in\mathcal P_{\mathrm{fin}}(\mathsf{Fm}_{Tab}^{\Sigma})
\land A\in\mathsf{Fm}_{Tab}^{\Sigma}
\land T\in\mathsf{TabTree}
\land b\in\mathsf{Branch}_{Tab}
\\
&\land\operatorname{BranchSet}(T)=\{b\}
\land\operatorname{rng}(b)=\Gamma\cup\{\operatorname{neg}(A)\}
\\
&\land
\Bigl(
\Gamma=\varnothing
\Rightarrow
\exists r\in\mathbb N\,
\bigl(
\operatorname{Node}(T)=\{r\}
\land\operatorname{Edge}(T)=\varnothing
\land\operatorname{root}(T)=r
\land b:1\to\mathsf{Fm}_{Tab}^{\Sigma}
\land b(0)=\operatorname{neg}(A)
\land\operatorname{lab}_{T}(r)=\operatorname{neg}(A)
\bigr)
\Bigr).
\end{aligned}
